def histogram(test):
    """
    Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Args:
        test (str): A string of space-separated lowercase letters

    Returns:
        dict: A dictionary where keys are letters and values are their counts
    """

    # Split the input string into a list of words
    words = test.split()

    # Initialize an empty dictionary to store the count of each letter
    hist_dict = {}

    # Iterate over each word in the list
    for word in words:
        # If the word is already in the dictionary, increment its count by 1
        if word in hist_dict:
            hist_dict[word] += 1
        # Otherwise, add it to the dictionary with a count of 1
        else:
            hist_dict[word] = 1

    # Find the maximum count in the dictionary
    max_count = max(hist_dict.values(), default=0)

    # Filter the dictionary to only include letters with the maximum count
    result = {letter: count for letter, count in hist_dict.items() if count == max_count}

    return result

# Test cases
print(histogram('a b c'))  # {'a': 1, 'b': 1, 'c': 1}
print(histogram('a b b a'))  # {'a': 2, 'b': 2}
print(histogram('a b c a b'))  # {'a': 2, 'b': 2}
print(histogram('b b b b a'))  # {'b': 4}
print(histogram(''))  # {}
